 * Cell address parsing and column ordering.
 *
 * An address is one or two letters naming a column (A..Z, then AA..ZZ) and
 * one to three digits naming a row of at least 1. The row is a number, so
 * "A1" and "A01" name the same cell; the normalized key uses the numeric
 * row, not the literal digit text.
 */

const ADDRESS_RE = /^([A-Z]{1,2})([0-9]{1,3})$/

/** Column letters to a 1-based ordinal: A=1 .. Z=26, AA=27 .. ZZ=702. */
export function colNumber(letters) {
  let n = 0
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

/** The inverse of colNumber. */
export function numToCol(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

/**
 * Parses an already upper-cased word as a strict cell address.
 * Returns { col, row, key } or null when the word is outside the
 * addressable range.
 */
export function parseAddress(word) {
  const m = ADDRESS_RE.exec(word)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  return { col: m[1], row, key: m[1] + String(row) }
}

/** Compares two normalized address keys by column then row. */
export function compareAddressKeys(a, b) {
  const pa = ADDRESS_RE.exec(a)
  const pb = ADDRESS_RE.exec(b)
  const ca = colNumber(pa[1])
  const cb = colNumber(pb[1])
  if (ca !== cb) return ca - cb
  return parseInt(pa[2], 10) - parseInt(pb[2], 10)
}

/**
 * Expands a range between two corner words (in either orientation) into
 * the list of normalized address keys it covers, in ascending column then
 * ascending row order. Returns null when either corner is outside the
 * addressable range.
 */
export function expandRange(wordA, wordB) {
  const a = parseAddress(wordA)
  const b = parseAddress(wordB)
  if (!a || !b) return null
  const colMin = Math.min(colNumber(a.col), colNumber(b.col))
  const colMax = Math.max(colNumber(a.col), colNumber(b.col))
  const rowMin = Math.min(a.row, b.row)
  const rowMax = Math.max(a.row, b.row)
  const keys = []
  for (let c = colMin; c <= colMax; c++) {
    const letters = numToCol(c)
    for (let r = rowMin; r <= rowMax; r++) keys.push(letters + String(r))
  }
  return keys
}
"}

