{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-kMDj6G/src/formulaLexer.js","content":"/**
 * Tokenizer for a formula body (the text after the leading "=").
 */

function isDigit(c) {
  return c >= '0' && c <= '9'
}

function isLetter(c) {
  return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')
}

export function tokenize(s) {
  const tokens = []
  let i = 0
  const n = s.length
  while (i < n) {
    const c = s[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (isDigit(c)) {
      let j = i + 1
      while (j < n && isDigit(s[j])) j++
      if (s[j] === '.' && isDigit(s[j + 1])) {
        let k = j + 1
        while (k < n && isDigit(s[k])) k++
        tokens.push({ type: 'NUM', value: s.slice(i, k) })
        i = k
        continue
      }
      tokens.push({ type: 'NUM', value: s.slice(i, j) })
      i = j
      continue
    }
    if (isLetter(c)) {
      let j = i + 1
      while (j < n && (isLetter(s[j]) || isDigit(s[j]))) j++
      tokens.push({ type: 'WORD', value: s.slice(i, j) })
      i = j
      continue
    }
    if (c === '<') {
      if (s[i + 1] === '=') {
        tokens.push({ type: 'LE' })
        i += 2
      } else if (s[i + 1] === '>') {
        tokens.push({ type: 'NE' })
        i += 2
      } else {
        tokens.push({ type: 'LT' })
        i += 1
      }
      continue
    }
    if (c === '>') {
      if (s[i + 1] === '=') {
        tokens.push({ type: 'GE' })
        i += 2
      } else {
        tokens.push({ type: 'GT' })
        i += 1
      }
      continue
    }
    const single = {
      '=': 'EQ',
      '+': 'PLUS',
      '-': 'MINUS',
      '*': 'STAR',
      '/': 'SLASH',
      '^': 'CARET',
      '(': 'LP',
      ')': 'RP',
      ',': 'COMMA',
      ':': 'COLON',
    }
    if (single[c]) {
      tokens.push({ type: single[c] })
      i++
      continue
    }
    tokens.push({ type: 'INVALID', value: c })
    i++
  }
  tokens.push({ type: 'EOF' })
  return tokens
}
"}

