{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-kMDj6G/src/formulaParser.js","content":"/**
 * Recursive-descent parser for a formula body. Precedence, loosest first:
 * comparisons, then + -, then * /, then ^ (right-associative), then a
 * leading sign (binds tighter than ^). A range (A1:B3) is grammatical only
 * as a whole function argument.
 *
 * Returns the AST, or null when the grammar does not accept the body.
 */
import { tokenize } from './formulaLexer.js'

const COMPARE_OPS = new Set(['EQ', 'NE', 'LT', 'LE', 'GT', 'GE'])

class ParseError extends Error {}

function parseTokens(tokens) {
  let pos = 0
  const peek = () => tokens[pos]
  const next = () => tokens[pos++]
  const expect = (type) => {
    if (peek().type !== type) throw new ParseError('unexpected token')
    return next()
  }

  function parseComparison() {
    let left = parseAdditive()
    while (COMPARE_OPS.has(peek().type)) {
      const op = next().type
      const right = parseAdditive()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  function parseAdditive() {
    let left = parseMultiplicative()
    while (peek().type === 'PLUS' || peek().type === 'MINUS') {
      const op = next().type
      const right = parseMultiplicative()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  function parseMultiplicative() {
    let left = parsePower()
    while (peek().type === 'STAR' || peek().type === 'SLASH') {
      const op = next().type
      const right = parsePower()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  function parsePower() {
    const left = parseUnary()
    if (peek().type === 'CARET') {
      next()
      const right = parsePower()
      return { type: 'bin', op: 'CARET', left, right }
    }
    return left
  }

  function parseUnary() {
    if (peek().type === 'PLUS' || peek().type === 'MINUS') {
      const op = next().type
      const operand = parseUnary()
      return { type: 'unary', op, operand }
    }
    return parsePrimary()
  }

  function parsePrimary() {
    const t = peek()
    if (t.type === 'NUM') {
      next()
      return { type: 'num', value: Number(t.value) }
    }
    if (t.type === 'LP') {
      next()
      const e = parseComparison()
      expect('RP')
      return e
    }
    if (t.type === 'WORD') {
      next()
      const upper = t.value.toUpperCase()
      if (peek().type === 'LP') {
        next()
        const args = parseArgList()
        expect('RP')
        return { type: 'call', name: upper, args }
      }
      if (upper === 'TRUE') return { type: 'bool', value: true }
      if (upper === 'FALSE') return { type: 'bool', value: false }
      return { type: 'addr', word: upper }
    }
    throw new ParseError('unexpected token')
  }

  function parseArgList() {
    const args = []
    if (peek().type === 'RP') return args
    args.push(parseArg())
    while (peek().type === 'COMMA') {
      next()
      args.push(parseArg())
    }
    return args
  }

  function parseArg() {
    if (peek().type === 'WORD') {
      const save = pos
      const w1 = next().value.toUpperCase()
      if (peek().type === 'COLON') {
        next()
        if (peek().type === 'WORD') {
          const w2 = next().value.toUpperCase()
          if (peek().type === 'COMMA' || peek().type === 'RP') {
            return { type: 'range', a: w1, b: w2 }
          }
        }
      }
      pos = save
    }
    return parseComparison()
  }

  const result = parseComparison()
  expect('EOF')
  return result
}

export function parseFormula(body) {
  try {
    const tokens = tokenize(body)
    if (tokens.some((t) => t.type === 'INVALID')) return null
    return parseTokens(tokens)
  } catch (e) {
    if (e instanceof ParseError) return null
    throw e
  }
}
"}

