 * The four value kinds a cell can hold: number, text, boolean, error.
 */

const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

const NUMBER_LITERAL_RE = /^-?[0-9]+(\.[0-9]+)?$/

export const num = (v) => ({ t: 'num', v })
export const text = (v) => ({ t: 'text', v })
export const bool = (v) => ({ t: 'bool', v })
export const err = (v) => ({ t: 'err', v })

/** Parses non-formula cell content into a value. */
export function parseLiteral(content) {
  if (content === '') return num(0)
  if (NUMBER_LITERAL_RE.test(content)) return num(Number(content))
  if (ERROR_TOKENS.has(content)) return err(content)
  return text(content)
}

/** Rounds a finite number to ten significant digits and prints it as JS would. */
export function formatNumber(n) {
  if (n === 0) return '0'
  const rounded = Number(n.toPrecision(10))
  return String(rounded)
}

export function formatValue(v) {
  switch (v.t) {
    case 'num':
      return formatNumber(v.v)
    case 'text':
      return v.v
    case 'bool':
      return v.v ? 'TRUE' : 'FALSE'
    case 'err':
      return v.v
    default:
      throw new Error('unreachable')
  }
}
"}

