import { parseAddress, expandRange } from './address.js'
import { parseFormula } from './formulaParser.js'
import { num, bool, err, parseLiteral } from './values.js'

const AGGREGATE_NAMES = new Set(['SUM', 'MIN', 'MAX', 'AVG', 'COUNT'])

/** Evaluates every declared cell and returns a Map of key -> value. */
export function evaluateSheet(sheet) {
  const memo = new Map()
  const visiting = new Set()
  const ctx = { sheet, memo, visiting }
  for (const key of sheet.keys()) cellValue(key, ctx)
  return memo
}

function cellValue(key, ctx) {
  const { sheet, memo, visiting } = ctx
  if (memo.has(key)) return memo.get(key)
  if (visiting.has(key)) return err('#CYCLE!')
  const content = sheet.get(key)
  if (content === undefined) {
    const v = num(0)
    memo.set(key, v)
    return v
  }
  visiting.add(key)
  let result
  if (content.startsWith('=')) {
    const ast = parseFormula(content.slice(1))
    result = ast ? evalNode(ast, ctx) : err('#ERR!')
  } else {
    result = parseLiteral(content)
  }
  visiting.delete(key)
  memo.set(key, result)
  return result
}

function evalNode(node, ctx) {
  switch (node.type) {
    case 'num':
      return num(node.value)
    case 'bool':
      return bool(node.value)
    case 'addr': {
      const info = parseAddress(node.word)
      if (!info) return err('#REF!')
      return cellValue(info.key, ctx)
    }
    case 'unary':
      return evalUnary(node, ctx)
    case 'bin':
      return evalBin(node, ctx)
    case 'call':
      return evalCall(node, ctx)
    default:
      throw new Error('unreachable')
  }
}

function toNumber(v) {
  if (v.t === 'num') return { ok: true, value: v.v }
  if (v.t === 'bool') return { ok: true, value: v.v ? 1 : 0 }
  return { ok: false }
}

function evalUnary(node, ctx) {
  const operand = evalNode(node.operand, ctx)
  if (operand.t === 'err') return operand
  const n = toNumber(operand)
  if (!n.ok) return err('#VALUE!')
  const result = node.op === 'MINUS' ? -n.value : n.value
  if (!Number.isFinite(result)) return err('#DIV/0!')
  return num(result)
}

const RANK = { num: 0, text: 1, bool: 2 }

function compareValues(l, r) {
  if (RANK[l.t] !== RANK[r.t]) return RANK[l.t] < RANK[r.t] ? -1 : 1
  if (l.t === 'num') return l.v - r.v
  if (l.t === 'text') return l.v < r.v ? -1 : l.v > r.v ? 1 : 0
  return (l.v ? 1 : 0) - (r.v ? 1 : 0)
}

function evalBin(node, ctx) {
  const l = evalNode(node.left, ctx)
