/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */
import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheetParser.js'
import { evaluateSheet } from './evaluate.js'
import { cellDeps } from './deps.js'
import { formatValue } from './values.js'
import { compareAddressKeys } from './address.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exitCode = 2
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'values' && mode !== 'deps') {
    fail('usage: cli.js values|deps')
    return
  }

  const input = readFileSync(0, 'utf8')
  let sheet
  try {
    sheet = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(e.message)
      return
    }
    throw e
  }

  const keys = [...sheet.keys()].sort(compareAddressKeys)
  let out = ''
  if (mode === 'values') {
    const values = evaluateSheet(sheet)
    for (const key of keys) out += `${key}=${formatValue(values.get(key))}\n`
  } else {
    for (const key of keys) {
      const deps = cellDeps(sheet.get(key))
      out += deps.length ? `${key}: ${deps.join(' ')}\n` : `${key}:\n`
    }
  }
  process.stdout.write(out)
}

main()
"}

